  <header>
    <h1>AI 2027<span class="sup">1</span></h1>
    <div class="authors">Daniel Kokotajlo, Scott Alexander, Thomas Larsen, Eli Lifland, Romeo Dean</div>
    <nav>
      <a href="#summary" class="btn">Summary</a>
      <a href="#research" class="btn">Research</a>
